INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Robot Taisen W', 'Super Robot Taisen W is part of the Super Robot Wars franchise and was published for the Nintendo DS by Banpresto. It is the first Super Robot Wars game released for the Nintendo DS. Like some DS games, special features can be unlocked by starting a new game with any of the Game Boy Advance era games inserted into SLOT 2.' FROM games WHERE igdb_id = 21405 ON CONFLICT (game_id, language_code) DO NOTHING;
