INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Record of Agarest War', 'Record of Agarest War is a tactical RPG where players guide multiple generations of heroes through an intergenerational story. The game combines strategic turn-based combat with a unique system where the protagonist''s choice of romantic partner determines the abilities and attributes of the next generation''s main character. Players advance through five distinct eras, building relationships, engaging in grid-based battles, and shaping their legacy across generations.' FROM games WHERE igdb_id = 7158 ON CONFLICT (game_id, language_code) DO NOTHING;
