INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Solfege', 'Kagura is a high school student who returns to her old school after three years abroad. There, she wants to meet again her sempai Sukune, who she admired since she was little. But she has also more friends: the active Chiho and the serene Kotomi. But it seems Sukune has forgotten her! What''s happening...?' FROM games WHERE igdb_id = 240067 ON CONFLICT (game_id, language_code) DO NOTHING;
