INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tomb Raider: Anniversary', 'Tomb Raider: Anniversary is a remake of the original Tomb Raider with a technically more advanced graphics engine. It has the same basic storyline, though some cutscenes and much of the dialogue within have been expanded or modified in other ways. Locations correspond to those of the original version and are accessed in the same order, but have been re-designed with different layouts and mostly completely different puzzles which allow implementation of new moves: swinging on ropes and using a grappling hook at specific points.' FROM games WHERE igdb_id = 1162 ON CONFLICT (game_id, language_code) DO NOTHING;
