INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Starfighter: Disputed Galaxy', 'Starfighter: Disputed Galaxy is a free-roaming, action-packed, top-down space shooter game. Choose between Humans or Aliens, battle your way up the ranks by doing various types of missions, buying and upgrading ships, buying and installing a large range of weapons and utilities and mining asteroids. Players can team up by joining gangs. There is a large galaxy to explore, divided into 400 sectors containing space stations, planets, black holes, worm holes and more.' FROM games WHERE igdb_id = 331174 ON CONFLICT (game_id, language_code) DO NOTHING;
