INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('myth-makers-orbs-of-doom', 5041, '2007-10-26', 20, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4ai8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/xdlummhftnshycgn9ds1.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Myth Makers: Orbs of Doom', 'Join the Myth Makers in an all new adventure! The evil Sinster Rebus is trying to take over the Myth Realm! He has created 8 magical crystals known as the Orbs of Doom and has trapped each of the Myth Makers within them. Now no one can stand in his way ... or at least that''s what Sinster Rebus thinks. Can the Myth Makers roll their way through the puzzling Myth Realm and save themselves from the clutches of Sinster Rebus? They must venture through 40 brain busting levels set across 5 lavish environments!' FROM games WHERE igdb_id = 5041 ON CONFLICT (game_id, language_code) DO NOTHING;
