INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slingoween', 'Slingoween is a Halloween-themed mini-game where players control a pumpkin-headed character, Sling, using a grappling mechanic to collect candy and avoid obstacles like ghosts and pumpkins. The objective is to navigate through levels by attaching to "grabs" to turn them green, ultimately reaching a portal to advance.' FROM games WHERE igdb_id = 338940 ON CONFLICT (game_id, language_code) DO NOTHING;
