INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LEGO Exo-Force: Sentai Showdown', 'Sentai Showdown was a series of 3 web based first-person shooters released in 2007 on LEGO''s website to tie in with the Exo-Force theme. Each showdown session contains a battle arena were you chase and fight waves of enemies in your mech of choice, or a customized one with mix and matched parts. There were also 3 training sessions that were stationary aim training minigames.' FROM games WHERE igdb_id = 343211 ON CONFLICT (game_id, language_code) DO NOTHING;
