INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LocoRoco Cocoreccho', 'LocoRoco Cocoreccho! (or Oideyo LocoRoco!! BuuBuu Cocoreccho! (おいでよロコロコ！！ BuuBuu Cocoreccho!?), in Japan, meaning "LocoRoco Come On Over(!)! BuuBuu Cocoreccho!") is a video game in the LocoRoco series released on the PlayStation Network for PlayStation 3 on September 21, 2007.[1] Described as an "interactive screensaver",[2] LocoRoco Cocoreccho! features an autonomous two-dimensional environment in which the world and characters play even without input from the player.[3] The game is capable of running at full high-definition 1080p display resolution.[2]' FROM games WHERE igdb_id = 1460 ON CONFLICT (game_id, language_code) DO NOTHING;
