INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Surf''s Up', 'When the Surf''s Up, Cody Maverick comes running to hit the tubes with his board. Based on the 2007 film, Surf''s Up follows the story of a young penguin surfer from Shiverpool Antarctica who enters the Big Z Memorial Surf Off on the island of Pen Gu. Single gamers may select from ten playable characters and then work their way through several environments including Shiverpool, Pen Gu, and the volcanic area. With friends, players may compete in a variety of competitions with such characters as Tank, Big Z, and Cody.' FROM games WHERE igdb_id = 4191 ON CONFLICT (game_id, language_code) DO NOTHING;
