INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Enemy Territory: Quake Wars', 'Enemy Territory: Quake Wars is a first-person shooter video game developed by Splash Damage and published by Activision for Microsoft Windows, Linux, Mac OS X, PlayStation 3 and Xbox 360. The prequel to Quake II, Quake Wars is set in the same science fiction universe as Quake II and Quake 4, with a minimal back-story serving as a prequel to Quake II. It is the second multiplayer-focused game in the Quake series after Quake III Arena.
