INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('face-training-facial-exercises-to-strengthen-and-relax-from-fumiko-inudo', 91846, '2007-08-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8mnu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scthpj.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Face Training: Facial Exercises to Strengthen and Relax from Fumiko Inudo', 'Face Training: Facial exercises to strengthen and relax from Fumiko Inudo Facening (JP) is a Nintendo DS video game released in 2006 by Nintendo. Nintendo first party Intelligent Systems developed the game, while Fumiko Inudo, a "beauty expert" in Japan, assisted with the development of the game. In Japan, the game came packaged with a camera that could be placed in the Game Boy Advance slot of the original Nintendo DS and DS Lite. In Europe, the game is now a DSi exclusive, since it utilize the DSi camera feature. The game is a face training game that is capable of reading various expressions made with the user''s face. The game was one of the many Touch Generations video games, and was unfortunately not released in the U.S. or outside of Europe or Japan.
