INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bikkuriman-daijiten', 269720, '2007-08-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7667.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bikkuriman Daijiten', 'Bikkuriman Daijiten is a Bikkuriman game released by 3 o''Clock for Nintendo DS in August 2007. Similar to the 1988 Bikkuriman Daijikai, the game is an (improved) encyclopedia of the Akuma vs. Tenshi Seal series, containing seals from all 31 series. In the beginning the seals are all black and white, but players can obtain points and use them to buy Bikkuriman Choco, where the seals can be obtained and later viewed in color. Depending of the seal, once obtained they will also have extra content unlocked, like extra information, their alternate versions from other products (like Bikkuriman Ice), and the ability to move foil cards (like Black Zeus) to see their colors. Points are earned in three ways: Once per day a certain amount is given to the player, by answering questions in the quiz mode, or trading duplicated and unwanted (becoming black and white again and locking bonus content if all are given) seals for 5-150 (depending of the seal) points each. It is also possible to trade seals with other players.' FROM games WHERE igdb_id = 269720 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_platforms (game_id, platform_id) SELECT g.id, p.id FROM games g, platforms p WHERE g.igdb_id = 269720 AND p.igdb_id = 20 ON CONFLICT DO NOTHING;
INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('digimon-world-data-squad', 20761, '2007-10-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2px7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/zfmu6bxmvya1zkqtqxgi.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Digimon World Data Squad', 'The game is set in the Digimon Data Squad universe, and revolves around the Seven Great Demon Lords. In this game the player will be able to control the four main Savers characters, Marcus Damon, Thomas H. Norstein, Yoshino "Yoshi" Fujieda, and Keenan Crier along with their respective Digimon partners. The graphics for this game are cel-shaded and the battle system is similar to the Battle Terminal (a Japanese-only arcade game). The game is classified as a "special genre", called a "Dramatic/Innovative RPG", which means that the Digimon partners are affected by how you, the player, treat them. The way your Digimon evolves will be similar to Digimon World; the Digimon will be affected by how you take care of it and, depending on that, will digivolve into different types of Digimon. In Digimon World Data Squad, a new type of digivolution method is used, called the Galactica Evolution System: this will determine what Digimon your partner will evolve into. There will also be new, original characters for this game, meaning that these characters are exclusive to Digimon World Data Squad, and will not appear in any other Digimon Data Squad media.' FROM games WHERE igdb_id = 20761 ON CONFLICT (game_id, language_code) DO NOTHING;
