INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Boku wa Kimi dake o Mitsumeru Gaiden: Saber Tiger Hen', 'Three mysterious suicides have occurred in Tokyo. The victims belonged to the juvenile gangster group “Sabre-tooth Tiger” led by Takumi, Kazu and Hisa. The group is ordered to reveal the truth behind these violence incidents. What shocking facts will get uncovered?' FROM games WHERE igdb_id = 83101 ON CONFLICT (game_id, language_code) DO NOTHING;
