INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BlackSite: Area 51', 'Modern day fears explode onto the streets of a small American town swarming with alien life. The government is desparate, struggling to contain secrets so terrible they can no longer be kept. You are Aeran Pierce, a Special Forces assassin thrown into one of the most explosive moments in American history. Everything hinges on your actions in BlackSite: Area 51.' FROM games WHERE igdb_id = 5730 ON CONFLICT (game_id, language_code) DO NOTHING;
