INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Digimon World Dusk', 'Digimon World Dusk, originally released as Digimon Story Moonlight in Japan, is a Digimon video game for the Nintendo DS handheld game console. It was released in Japan on March 29, 2007 and North America on September 18, 2007. It serves as the second game in the Digimon Story series, though it was marketed as a game within the Digimon World series in North America.' FROM games WHERE igdb_id = 78285 ON CONFLICT (game_id, language_code) DO NOTHING;
