INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Sword and Fairy 4', 'The Legend of Sword and Fairy 4 is an action role-playing game developed by Softstar Technology (Shanghai) Co., Ltd.. It is the fifth installment in The Legend of Sword and Fairy (or Chinese Paladin) video game series, and serves as a prequel to the third game. The game incorporates elements of wuxia, shenmo and fantasy.' FROM games WHERE igdb_id = 78465 ON CONFLICT (game_id, language_code) DO NOTHING;
