INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bee-ball', 40720, '2007-02-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5yng.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bee-Ball', 'In the animal kingdom, bees are widely known as efficient workers. But there''s an interesting fact that we as humans don''t know--bees enjoy having fun! Every year bees from many places gather in one spot to play in a competitive tournament of Bee-Ball! This unique insect game is a mix of tennis and volleyball where bees hit a honey ball over a net using a racquet. A bee judge watches over the match and serves new balls as needed. If the ball touches the floor or flies out of bounds, a point is scored. Avoid fouling the ball out, use your dexterity to block your opponent''s shots, slam the ball to score, learn new tactics to outwit your opponent, and you could be the next Bee-Ball champion!
