INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RealPlay Puzzlesphere', 'Explore a world full of challenging puzzles with Realplay Puzzlesphere for the Playstation 2. This engaging game offers a collection of diverse and intriguing puzzles that will put your brain to work. Solve challenging riddles, test your logic and improve your thinking skills while experiencing immersive gameplay. Dive into the fun of brain-teasing challenges and enjoy hours of entertainment with this fascinating puzzle game.
