INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Switchball', 'Have a ball with the PlayStation3 computer entertainment system! Travel as a transformable ball through five worlds and 30 levels of stunning 3-D mazes. Journey your way through traps, puzzles and challenges suspended in the sky, earning PlayStation3 system trophies as you go! Play as a single player, or try Race and Co-op multiplayer modes to compete with your friends!
