INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ar-tonelico-ii-melody-of-metafalica', 43658, '2007-10-25', 65, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co25mw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar8e9.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ar tonelico II: Melody of Metafalica', 'The setting for the game is the same as the previous game: the planet of Ar Ciel, albeit centered on a different region this time. The Tower of Ar tonelico from Metafalss is different from the tower in the first game since it doesn''t look like a tower initially, but still has some of the same essential facilities (Rinkernator, Plasma Bell (represented as the Lift Generators) and Musical Corridor). The Song Magics are still used like programs, but in this tower there are two Song Magic servers: the Sol Marta server and the Infel Phira Server. The Sol Marta server is located in the upper zone of the tower, acting like a stationary satellite. It is collocated with the S. P. U. and Rinkernator and is the main server for the tower. The Infel Phira server is located in a satellite that orbits the sky around the tower and shares its name with said server. The Sol Marta satellite is a relay station used to increase the range of Song Magic usage of the first tower, so it works with the same kind of hymmnos and executes the EXEC variety of hymns. Plus, it also has the function of receiving energy from the first tower and sending it to the second tower. On the other hand, the Infel Phira server works with another kind of hymmnos called the Pastalia hymmnos, and executes the METHOD variety of hymns.' FROM games WHERE igdb_id = 43658 ON CONFLICT (game_id, language_code) DO NOTHING;
