INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chess.com', 'Play chess online with millions of players around the world! Enjoy free unlimited games and improve your chess rating with 50,000+ tactics puzzles, interactive lessons and videos, and a powerful computer opponent. Unlock your inner chess master today!' FROM games WHERE igdb_id = 121957 ON CONFLICT (game_id, language_code) DO NOTHING;
