INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Singstar: Svenska Hits Schlager', 'SingStar: Svenska Hits Schlager is a karaoke game featuring 30 songs by Swedish artists. There are no changes to the gameplay formula: player(s) sing into a microphone and the game gives points based on the performance. The only basis of assessment is if the correct note is hit with the correct timing; the sung words or octave does not play into the result.' FROM games WHERE igdb_id = 43483 ON CONFLICT (game_id, language_code) DO NOTHING;
