INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Little Busters!', 'Little Busters! is a Japanese visual novel developed by Key. The story follows the life of Riki Naoe, a high school student who has been a member of a group of friends named the Little Busters since childhood. Riki brings multiple girls at his school into the Little Busters to have enough people to play a baseball game. The game is rated for all ages in Japan, but a version containing adult content named Little Busters! Ecstasy exists as well.' FROM games WHERE igdb_id = 7364 ON CONFLICT (game_id, language_code) DO NOTHING;
