INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Close Combat: Modern Tactics', 'A tactical wargame based on a US marine corp training simulator. It comes with 25 Modern scenarios based on real-world and hypothetical conflicts. Fight on hypothetical battlefields ranging in style from backwoods America to the streets of Iraq and the former Soviet republics. A scenario editor is also included, making it easy to setup your own battles with modern opposing forces.' FROM games WHERE igdb_id = 21519 ON CONFLICT (game_id, language_code) DO NOTHING;
