INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doraemon Wii: Himitsu Dougu-ou Ketteisen!', 'Doraemon Wii: Himitsu Dougu-ou Ketteisen! is a party game on Wii, released on 2007. Like Mario Party 8, you can roll dice with a Wii remote or play mini-games with four people. It was the first Wii software in the Doraemon game series. Mainly a board game.' FROM games WHERE igdb_id = 4818 ON CONFLICT (game_id, language_code) DO NOTHING;
