INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'An American Tail', 'An American Tail is a game based on the animated movie of the same name. It consists of ten levels (six main ones, four bonus) based on scenes from the movie. Animated scenes from the film are used as cut-scenes. It tells the story how Fievel Mousekewitz and his family leave Russia for America. He becomes separated from his family when a storm hits the ship and eventually ends up in New York.' FROM games WHERE igdb_id = 68257 ON CONFLICT (game_id, language_code) DO NOTHING;
