INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dynasty Warriors 6', 'Based on the epic novel, Romance of the Three Kingdoms, the genre-defining Dynasty Warriors series depicts the massive battles ignited by the fall of the Han Dynasty when three rebellious states moved to overthrow the Emperor of China. Expanding over the original with a new combat engine, Dynasty Warriors 6 delivers the exhilaration of single-handedly destroying thousands of soldiers on massive fields of combat. The lightning-fast king-fu fighting, fluid animation, intuitive combat system and immersive game environments push the limits of tactical action!' FROM games WHERE igdb_id = 6975 ON CONFLICT (game_id, language_code) DO NOTHING;
