INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Fantasy II: 20th Anniversary Edition', 'This version was released on the PSP. Marking the 20th anniversary of the original Japanese Final Fantasy, Square Enix released the 20th Anniversary collection for Sony''s emerging PlayStation Portable handheld. Square Enix took full advantage of the format, restoring the original PlayStation release''s FMV sequences, upscaling and further refining the Dawn of Souls release for the PSP''s wider screen, and adding an entirely new set of bonus dungeons known as the Arcane Labyrinths for players seeking a greater challenge.' FROM games WHERE igdb_id = 121717 ON CONFLICT (game_id, language_code) DO NOTHING;
