INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Professor Fizzwizzle and the Molten Mystery', 'While on a well deserved vacation, Professor Fizzwizzle''s investigation of a strange volcano has landed him in a Molten Mystery! Now it''s up to you to master exciting new gadgets, outwit the Bat-Bots, and vanquish a truly cunning villain! Can the professor count on you to help? With over 200 levels spanning 3 difficulties (kids, regular, and advanced) Professor Fizzwizzle can keep an entire family occupied for hours of skill-building and problem-solving!' FROM games WHERE igdb_id = 16175 ON CONFLICT (game_id, language_code) DO NOTHING;
