INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fury', 21227, '2007-12-31', 50, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3wot.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc61my.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fury', 'Fury was a game billed as an Arena-based PvP MMO without PvE content. Players engaged in combat as groups or as individuals in 3 different war zone game types: Bloodbath (everybody vs everybody), Vortex (team based capture the flag variant), Elimination (team based elimination best out of 3). A fourth game type, Fortress (large scale fortress sieges), was being developed but never finished. Players progressed in ranks, won equipment, and bought skills and abilities which they used to build their character in a completely free-form skill-based system. You could save your equipment and ability layout as an "incarnation" and switch incarnation between war zones. There was no specific player ''class'' as in other MMOs nor did you need to have alternate characters to explore other character aspects as you could just rebuild a different incarnation of yourself.' FROM games WHERE igdb_id = 21227 ON CONFLICT (game_id, language_code) DO NOTHING;
