INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Fantasy XII: Revenant Wings', 'One year after the events of FINAL FANTASY XII, the young protagonist Vaan travels the skies of Ivalice with his trusted navigator Penelo at his side. Their treasure hunting adventures take them to the sky continent of LemurÃs where they meet Llyud, a member of the aegyl race. These mysterious winged people have been living on the floating continent for centuries, but a disturbance has allowed treasure-seeking sky pirates to breach their once-hidden territory. It falls to Vaan and his band of young sky pirates to stand up against the trespassers, and defend this extraordinary world and its people.' FROM games WHERE igdb_id = 392 ON CONFLICT (game_id, language_code) DO NOTHING;
