INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harvest Moon DS: Island of Happiness', 'In Harvest Moon: Island of Happiness you develop the island by growing crops and taking care of animals and expanding your farm. The better you do, the more the island will grow, and the more others will start to move onto the island. Though it was not your original dream, now is you chance to create your very own paradise!' FROM games WHERE igdb_id = 3387 ON CONFLICT (game_id, language_code) DO NOTHING;
