INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Mario Flash', 'Super Mario Flash (also known and abbreviated as SMF1) is the first of two online games developed by Pouetpu and released on pouetpu.pbworks.com before the creation of Pouetpu-games site. Super Mario Flash is entirely based off of the Nintendo game "Super Mario Bros.", and also combines several features of different games such "Super Mario Bros. 3".
