INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chicken Rush Deluxe', 'Hordes of savage meanies are invading, looking for the tastiest chickens around! Paula the hen needs to keep her fellow birds safe, and she needs your help. Guide Paula as she keeps these meanies at bay with her magic rifle that will turn her targets into cacti and stones. You''ll need careful and swift reactions to keep these chickens away from becoming dinner in Chicken Rush Deluxe!' FROM games WHERE igdb_id = 341617 ON CONFLICT (game_id, language_code) DO NOTHING;
