INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('etrian-odyssey', 14716, '2007-01-18', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6l7z.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/bri8tsu1yuknkcuptjr9.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Etrian Odyssey', 'In a vast and fertile land lies a small town known as Etria, a peaceful village that became famous for a startling discovery. A crack in the vast forest opened at Etria''s edge, leading downward like a gaping maw. It all began there... Your salvation in the labyrinth is in your own hands: Create your own team of adventurers to withstand the maze''s fierce battles, while creating your own dungeon maps using the Nintendo DS touch screen outside of combat. Lush 3D graphics and a world-class soundtrack puts an exquisite face on the mortal danger that lurks at every step.' FROM games WHERE igdb_id = 14716 ON CONFLICT (game_id, language_code) DO NOTHING;
