INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pawly-pets-my-vet-practice', 47807, '2007-03-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co99hx.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pawly Pets: My Vet Practice', 'Do you sometimes dream of being a vet doctor? With the game My Vet Practice this dream can come true. Build up your own practice, decide when to build which building and which patient to treat. Every day people come to you with their animals, guinea pigs, rabbits, budgerigars, cats, dogs and even horses. Sometimes it can even be necessary to accommodate the animals and take care of them for a couple of days, so that they get well and happy again quickly. Therefore you can build extra stables and accomodations. Feeding, playing with the pets, bear company, but also cleaning up and the daily treatment are your duties. For very demanding horse-patients, you can experience interesting things about horse whispering. But although the work with pets is a lot of fun, even the best vet doctor needs some time out. Then you take your own horse and go for a long ride at the beach, on meadows and fields or through the nearby forest. Stock up new energy to become the best vet doctor of all time.' FROM games WHERE igdb_id = 47807 ON CONFLICT (game_id, language_code) DO NOTHING;
