INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Metroid Prime 3: Corruption', 'The trilogy closes as corruption creeps over the universe… and into Samus Aran. Using the Wii Remote and Nunchuk, players control Samus as she partners with other bounty hunters, shoots down enemies, and explores alien worlds in a harrowing mission to stop the mutagenic Phazon from spreading across the galaxy.' FROM games WHERE igdb_id = 1111 ON CONFLICT (game_id, language_code) DO NOTHING;
