INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Naruto Shippuden: Gekitou Ninja Taisen! EX', 'Naruto Shippuden: Gekitou Ninja Taisen! EX is the fifth instalment of the Japanese-exclusive Gekitō Ninja Taisen series. This game was also the first Gekitō Ninja Taisen game to be released for the Nintendo Wii as well as the first entry into the EX sub-series.' FROM games WHERE igdb_id = 75838 ON CONFLICT (game_id, language_code) DO NOTHING;
