INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('tiger-woods-pga-tour-08', 5221, '2007-08-28', 76, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co39uh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/imve9iqunanoom6xvt2p.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tiger Woods PGA Tour 08', 'The game incorporates the FedExCup championship format (a collection of tournaments) with rounds of golf at Westchester Country Club, TPC Boston, Cog Hill, and East Lake. The putt preview has been improved, allowing the player to simulate the ball''s path once per individual spot, taking into accounts elements such as power, speed and elevation. On the Xbox 360 and the PS3, shots are not performed using the analog stick, but with the 3-point timed principle for start, power and accuracy. Shot Confidence is a new addition, keeping track of the player''s performance on certain courses, for specific puts and using certain clubs. Great performances raise the confidence, which translates into experience and better performance on specific courses. Low confidence leads to lower accuracy, a pumping heartbeat, and rumbling controls on the Wii.
