INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Umineko no Naku Koro ni: Episode 2 - Turn of the Golden Witch', 'Turn of the Golden Witch is the second arc in Umineko no Naku Koro ni. The arc follows Battler Ushiromiya and Beatrice as they battle over the existence of magic. This is the first arc wherein the "alternate existence" versions of characters from Rokkenjima make an appearance. The story focuses heavily on Rosa Ushiromiya and Shannon.' FROM games WHERE igdb_id = 79845 ON CONFLICT (game_id, language_code) DO NOTHING;
