INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'eXceed 3rd: Jade Penetrate Black Package', 'eXceed 3rd reboots the eXceed storyline, taking it in a new direction. In this installment, Rayne Lindwurm, a descendent of the Dragon Clan, fights her way through a tournament to become one of the 7 Cardinal Lords who rule her world, Pandemonium. Standing in her way are other competitors and their familiars, including her own older sister and heiress to the mighty Dragon Clan, Celestia Lindwurm.' FROM games WHERE igdb_id = 10967 ON CONFLICT (game_id, language_code) DO NOTHING;
