INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cookie-and-cream', 47704, '2007-06-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4tg7.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cookie & Cream', 'Cookie & Cream is an action/platformer where players navigate their way through challenging terrain on the top screen while solving puzzles and disarming traps on the touch screen below. Played as either a single-player game where one person controls both characters, or a cooperative game where one player maneuvers Cookie on the top screen while the other is in charge of Cream on the touch screen, Cookie & Cream is a unique combination of gaming genres. Single player game lets you use directional button and touch pen to control two characters at once. Cooperative game lets you and a friend work together to advance through levels. Wireless compatible for co-op play and WiFi compatible for four-player battles. Download play mode allows two to play select stages off one Game Card. Eight diversely themed worlds to traverse, including Desert World, Music World, Trick World and Water World. Nine challenging minigames to explore. [Agetec, Inc.]' FROM games WHERE igdb_id = 47704 ON CONFLICT (game_id, language_code) DO NOTHING;
