INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Elemental', 'Elemental is a color-matching game. The player clicks and drags the mouse cursor over a group of tiles to flip them and change their color. When three or more tiles have matching colors, they are removed from the game. Each stage has one of the classic elements (earth, wind, fire and water) as its theme.' FROM games WHERE igdb_id = 95377 ON CONFLICT (game_id, language_code) DO NOTHING;
