INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('beautiful-katamari', 6456, '2007-10-16', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co48qa.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/o9fdpudpwqxoamncikm6.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beautiful Katamari', 'Experience the new high-definition, next generation sights and sounds of Beautiful Katamari as the Prince takes on a new high-rolling adventure, with his famous cousins in tow, to save the Katamari universe once again after the King of All Cosmos has a very un-royal and unfortunate accident. As usual, the King of All Cosmos demands the service of his son, the Prince, to roll anything and everything up into massive clumps and set things right, bringing harmony once again to the Katamari Cosmos. To keep his son inspired, the King of All Cosmos will provide another fresh and memorable soundtrack that will have players moving and grooving to the beat as they roll through the absurd, yet wonderful world of Beautiful Katamari.' FROM games WHERE igdb_id = 6456 ON CONFLICT (game_id, language_code) DO NOTHING;
