INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Unreal Tournament III', 'Unreal Tournament 3 marks the return of the world''s premiere first-person shooter to Xbox 360. The full power of the Unreal Engine 3 is unleashed, taking graphics, gameplay, and challenge to a whole new level. Players engage in intense battles with other human players online, or against Unreal artificial intelligence that sets the industry standard. With the most powerful futuristic weapons and vehicles available, this is FPS action at its best!' FROM games WHERE igdb_id = 928 ON CONFLICT (game_id, language_code) DO NOTHING;
