INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Peggle', 'Take your best shot with energizing arcade fun! Aim, shoot, clear the orange pegs, then sit back and cheer as 10 whimsical teachers guide you to Peggle greatness. Conquer 55 fanciful levels with 10 mystical Magic Powers, racking up bonus points and shots you''ll smile about for weeks. Face off against your friends in Duel Mode, or tackle 75 extra-tricky challenges. It''s luck and skill and joyous thrills, and amidst all this fevered action only one question remains: Can you become a Peggle Master?' FROM games WHERE igdb_id = 3751 ON CONFLICT (game_id, language_code) DO NOTHING;
