INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Race 07', 'RACE 07 is a racing simulation video game that covers the 2006 and 2007 World Touring Car Championship seasons. It offers over 300 cars across 9 different racing classes, including touring cars, Formula 3000, Formula BMW, and Radical sports cars. Players can race on 32 international tracks with multiple layout options, featuring a sophisticated damage system and flexible race formats. It represents a significant expansion from previous SimBin racing titles, introducing single-seater racing classes and enhanced community-oriented features.' FROM games WHERE igdb_id = 10380 ON CONFLICT (game_id, language_code) DO NOTHING;
