INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Art of Murder: FBI Confidential', 'This is the story of young FBI agent Nicole Bonnet. Her first task is to solve a series of macabre murders where the victims are targeted as the wealthy and prominent of the community. The culprit’s weaponry is rare and leaves an unusual calling card by removing the heart of those they choose. The adventure begins in New York, but the clues will lead ambitious agent Bonnet as far as the Peruvian city of Cusco – the ancient capital of the Inca Empire, as well as on the border of the Amazon jungle.' FROM games WHERE igdb_id = 9986 ON CONFLICT (game_id, language_code) DO NOTHING;
