INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Company of Heroes: Opposing Fronts', 'The next chapter in the #1 rated RTS franchise thrusts players into a hellish war torn landscape to command two battle-hardened armies in relentless campaigns for honor and country. Players lead the tenacious British 2nd Army during the heroic World War II liberation of Caen, France, and command the German Panzer Elite as they struggle to repel the largest airborne invasion in history.' FROM games WHERE igdb_id = 1370 ON CONFLICT (game_id, language_code) DO NOTHING;
