INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney High School Musical', 'Relive the excitement of High School Musical anytime, anywhere with this compact handheld LCD game developed by Zizzle. Released in 2007, the game offers five built-in mini-games inspired by scenes from the hit Disney film. Players use physical buttons to navigate rhythm and memory challenges, all displayed on a classic black-and-white LCD screen. With character art and familiar themes, it’s designed for younger fans looking to experience the magic of East High on the go. No console required—just insert AAA batteries and start playing!' FROM games WHERE igdb_id = 245513 ON CONFLICT (game_id, language_code) DO NOTHING;
