INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Katekyou Hitman Reborn! DS: Shinuki Max! Vongola Carnival!!', 'Katekyou Hitman Reborn! DS: Shinuki Max! Vongola Carnival!! is a Japanese Nintendo DS game that was released on March 29, 2007. It is based on Akira Amano''s manga series, Katekyo Hitman Reborn!. The game includes a variety of minigames that follow scenarios from the anime adaptation.' FROM games WHERE igdb_id = 123339 ON CONFLICT (game_id, language_code) DO NOTHING;
