INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'M&M''s Break ''Em', 'Mr. Runch, a rotten and dangerous peanut, fiercely determined on being one of the M&M''s, just escaped the reject bin where he was discarded as ghastly! He''s on the loose in the Galaxy, and trying to kidnap and trap all of the M&M''s into crystals until he can get what he wants: the chance to become a real M&M''s candy!' FROM games WHERE igdb_id = 49422 ON CONFLICT (game_id, language_code) DO NOTHING;
