INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Anan Kanshuu: Onna-jikara Kinkyuu Up! DS', 'Aimed for the readers of the Japanese lifestyle magazine "An An", this game offers tips to become the perfect you in four categories: "body", "manner", "mental", and "love". You first answer questions that best describe you and then pick what you aim for, after which the game builds you an unique training regime from psychological tests to recipes.' FROM games WHERE igdb_id = 269549 ON CONFLICT (game_id, language_code) DO NOTHING;
