INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Indianapolis 500 Legends', 'Fight to the finish in a hand-built speed machine racing seven inches off the ground at nearly 180 mph through a moving minefield of crashes, spinning cars, rolling tires, and 32 rivals on the world''s most famous racetrack in Indianapolis 500 Legends, an arcade-style racing experience set in a dynamic era spanning 1961-1971. Players will experience the traditions, rivalries, terrifying speeds, jaw-dropping maneuvers and infamous events that characterized this historic period at the world-famous Indianapolis 500 race.' FROM games WHERE igdb_id = 4933 ON CONFLICT (game_id, language_code) DO NOTHING;
