INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '10 Talismans', 'The legend says that if you collect 10 talismans, wisdom, power and hapiness will be yours. Enter the mystical challenge of puzzles in the oriental world of 10 Talismans. Set off with swords, amulets, lanterns and much more to collect the mystical talismans. Play against the clock in Classic or take your time in Timeless.' FROM games WHERE igdb_id = 205801 ON CONFLICT (game_id, language_code) DO NOTHING;
