INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Build-A-Bearville', 'Bearville (formally known as Build-A-Bearville) was an online multiplayer game which opened in late October 2007 and closed in March 2015. The game was opened to further promote the Build A Bear Workshop franchise and allow kids to have a more magical experience; it allowed them to bring their bears - which were called ''Furry Friends'' - to life and play with them in an online community, which involved many activities such as minigames and making new friends.' FROM games WHERE igdb_id = 214613 ON CONFLICT (game_id, language_code) DO NOTHING;
