INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Katamari Damacy Mobile', 'Katamari Damacy Mobile (塊魂モバイル, Katamari Damashii Mobairu, lit. "Clump Spirit Mobile") is a video game developed by Namco Bandaifor the Mitsubishi P904i series of mobile phones for NTT DoCoMo. It was released in June 2007 in Japan. It is a spin-off of the "Katamari Series", the second game on a portable system and the third game produced without the involvement of series creator Keita Takahashi.
