INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Musika', '"Musika" is a rhythm game designed by Masaya Matsuura. The game plays a song from your iPod library and challenges you to press Select as soon as you recognize a letter or number in its title. The faster you do so, the more points you’ll earn, thanks to the scoring multiplier that increases by one with each correct response.' FROM games WHERE igdb_id = 94641 ON CONFLICT (game_id, language_code) DO NOTHING;
