INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('farming-simulator-2008', 3168, '2007-12-31', 30, 'https://images.igdb.com/igdb/image/upload/t_cover_big/ntyv21gif2hyw6rsvxf2.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Farming-Simulator 2008', 'In "Farming Simulator" you are a farmer and will experience the versatile everyday life of a Farmer. Take a seat behind the steering wheel of the different detailed agricultural engines and carry out your work in the fields. You’ve got to plow your fields, sow the seeds, reap or station the harvest to store it in the silo or deliver it to the next harbour. The life of a farmer is hard, and so the player has to steer his heavy vehicles around the clock to earn his keep of life. As in the real world of farming the weather isn’t always on your side, and rain and hail give you a hard time. Additionally different missions have to be mastered, you also have the possibility to move absolutely free within this huge game world.' FROM games WHERE igdb_id = 3168 ON CONFLICT (game_id, language_code) DO NOTHING;
