INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crazy Chicken: The Winged Pharaoh', 'On his mission to discover the lost tomb of Tut Chick Amun in Egypt and deliver it to a museum, Moorhuhn Indy has to look for clues spread out across 30 clay tablets. While still equipped with the same moves as in the previous games, players are now able to make use of a wider variety of items and objects related to Ancient Egyptian culture.' FROM games WHERE igdb_id = 144592 ON CONFLICT (game_id, language_code) DO NOTHING;
