INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tales of Innocence', 'The Imperial Capital of Regnum kept itself in peace during the long-lasting world war. Slowly, people with a "special power" began to appear. Feared by normal people, Regnum set out a law to capture all people with special powers. One day, Ruca, the son of a merchant in Regnum, realizes the special power within him...' FROM games WHERE igdb_id = 1208 ON CONFLICT (game_id, language_code) DO NOTHING;
