INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Indestruc2Tank', 'Indestruc2Tank, the long awaited sequel to the surprise hit IndestructoTank with tonnes of new features! All new hand animated graphics, an Improved Physics engine, three distinct game modes including a story mode with levels, bosses and a fully voice acted cast of characters! Earn medals by achieving goals and use them to unlock secrets such as alternate tank graphics and much much more! Armor games is proud to present Indestruc2Tank!' FROM games WHERE igdb_id = 10146 ON CONFLICT (game_id, language_code) DO NOTHING;
