INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Inuyasha: Secret of the Divine Jewel', 'Inuyasha: Secret of the Divine Jewel is an epic role player game released for the Nintendo DS platform. Inspired from Rumiko Takahashi''s popular animated TV and comic series, Inuyasha: Secret of the Divine Jewel takes you to a new level of gaming with intriguing game play and brilliant graphics. This epic role player game starts off with the detailed and engrossing stories of Inuyasha, Kagome, Miroku, Sango and Shippo. With features like intuitive command-based control scheme and the new Cover Fellow System (CFS), you will get Inuyasha and his friends to work together on the Nintendo DS in a in a battle to save the world from Sara, Lord Gorai and many more demons. Get yourself the Inuyasha: Secret of the Divine Jewel and conjure up some magic!' FROM games WHERE igdb_id = 20653 ON CONFLICT (game_id, language_code) DO NOTHING;
