INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rainforest Cascade', 'In this arcade puzzler, saving the rainforest involves tile-matching. A matrix of tiles in various forms is presented; swap adjacent tiles to create rows or columns of 3 or more, and these will be destructed. When triggering this, the areas under them will be turned into gold; you have to turn the entire level to gold (by creating matches over every square, including the corners) to complete it and receive a bonus with the time that you still haven''t used.' FROM games WHERE igdb_id = 69845 ON CONFLICT (game_id, language_code) DO NOTHING;
