INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Draglade', 'In the world of Draglade, Grapping has become the world''s premier spectator sport. Scientists will discover how to turn atmospheric Matter into energy. Soon thereafter, a means of harnessing this energy – G-Cons – will allow for the conversion of this power into a weapon called a “Glade”. When a Glade hits something, the Glade emits a sound. Fighters and entertainers quickly realized the potential of Grapping, as the music generated by the clashing Glades in combat provided an experience that couldn''t be matched in any other sport. In this world overcome by Grapping fever, four young indie Grappers – Hibito, Guy, Kyle, and Daichi – will strive to reach the ranks of the Major Grappers.' FROM games WHERE igdb_id = 21542 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 21542 AND c.slug = 'atlus' ON CONFLICT DO NOTHING;
