INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('toyshop-trouble', 40608, '2007-01-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5yne.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Toyshop Trouble', 'Ah, the Bahamas. Toyshop elves Patrick, Quincy, and Robert are laying on the beach, relaxing in the sun. Nothing could be finer than listening to the surf while enjoying a cold drink. A great reward for having gotten all of Santa''s toys painted in record time. Unfortunately for you, Patrick''s idea of "painting" toys was dumping them all in a bucket of gray paint. While this technically fulfilled his associates'' obligations (thus their trip to the Bahamas), the toys--alas--still have to be painted properly.
