INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'PQ2: Practical Intelligence Quotient 2', 'PQ2: Practical Intelligence Quotient 2 (also known as PQ2; Intelligent License 2 in Japan) is a puzzle game for the PlayStation Portable, and a sequel to PQ: Practical Intelligence Quotient. The game is based on testing the model of human intelligence developed by Dr. Masuo Koyasu at Kyoto University. 
