INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Petrovich and all, all, all...', 'A humorous point & click game based on Andrei Bilzho''s caricatures. The game introduces us to how and what that same Petrovich and other historical figures live on today. At 25 levels of the game we meet Pushkin, Grandfather Mazai, Chapaev, Kolobok, aliens and many other characters.' FROM games WHERE igdb_id = 250572 ON CONFLICT (game_id, language_code) DO NOTHING;
