INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tecno: The Base', 'Tecno: The Base is a sci-fi puzzle-FPS set in the eponymously named Tecno Base, a remote research outpost. An accident in one of the labs causes all the robots to malfunction and attack the human staff. Over the course of the game, you play two playable characters, Alexia and Mika, who must solve a series of puzzles to piece together what happened and escape the base.' FROM games WHERE igdb_id = 92029 ON CONFLICT (game_id, language_code) DO NOTHING;
