INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Onside Soccer', 'Complete Onside Soccer is a football simulation game programmed by Elite Systems and published by Telstar Electronic Studios for the PlayStation and Windows. It was released in 1996 in Europe and 1998 in Japan. It is one of the several games featured by Peter Schmeichel, like Peter Schmeichel Soccer or Soccer Superstars Peter Schmeiche This is a version of Onside Soccer developed for the 3DO Interactive Multiplayer, which was released in 2007 by OlderGames as a kind of an experiment.' FROM games WHERE igdb_id = 37125 ON CONFLICT (game_id, language_code) DO NOTHING;
