INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ChessRogue', 'ChessRogue is a console-based puzzle game loosely based on chess. You take the part of the sole survivor of your side, and battle through twenty-five levels to capture the opposing King. As you capture opposing pieces, you learn their tricks and become more powerful yourself.' FROM games WHERE igdb_id = 93479 ON CONFLICT (game_id, language_code) DO NOTHING;
