INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spyglass Board Games', 'Play with a friend on Xbox LIVE, or play against the computer. Use the Xbox Live Vision camera to personalize the game board, playing pieces, and video effects. Each game has custom pieces to choose from, such as a rook made of stone or a furry checkers piece. And you can customize the look with textures like marble, silver, and gel. Make each game your very own!' FROM games WHERE igdb_id = 106254 ON CONFLICT (game_id, language_code) DO NOTHING;
