INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Enigma', 'Enigma is a puzzle video game based on Oxyd, and is released under the GPL. Enigma continues to be very popular as an open source multi-platform derivative of Oxyd now that Oxyd is no longer maintained. The open source fangame Enigma has been praised in reviews. Enigma is a marble game.' FROM games WHERE igdb_id = 127886 ON CONFLICT (game_id, language_code) DO NOTHING;
