INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Adventures of Pinocchio', 'Adventures of Pinocchio is a video game, released for the Nintendo DS and Wii on May 8, 2009, developed and published by the now-defunct company Phoenix Games. While there is a variety of mini-games targeted for young children, the game has the peculiarity of having more of a movie, rather than playable portions. A PlayStation 2 version simply called "Pinocchio," was released three years prior the DS and Wii ports'' release.' FROM games WHERE igdb_id = 69034 ON CONFLICT (game_id, language_code) DO NOTHING;
