INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Black Sails', 'Three great naval countries have been fighting each other to gain control over the Caribbean’s for many years. With none of the sides being able to settle the score, the battle has brought nothing but chaos and disarray to the region. It is up to you to take part in this epic battle and bring the opposing countries finally to their knees.' FROM games WHERE igdb_id = 270339 ON CONFLICT (game_id, language_code) DO NOTHING;
