INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Empires in Arms', 'He who controls Europe, controls the world… Empires in Arms is the official licensed computer version of Australian Design Group''s classic board game. Empires in Arms is a seven player game of grand strategy during the Napoleonic period of 1805-1815. Playable either solitaire against the AI or by e-mail. Corps level with full diplomatic options to allow players complete freedom to fight it out for control of Europe any way they want to.' FROM games WHERE igdb_id = 215076 ON CONFLICT (game_id, language_code) DO NOTHING;
