INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Silent Hill: The Escape', 'Silent Hill: The Escape is a Silent Hill spin-off game, featuring first-person shooter-style gameplay. Its characteristic feature is a gameplay mechanic called gesture technology, which is a method of controlling the actions in the game via image feedback from the mobile device''s built-in camera. The game objective is for the player to make their way through ten levels by finding the key and bringing it to the locked door at the end of each level. The player must slide their fingers to move the character in a first person perspective and tap the screen to shoot enemies.' FROM games WHERE igdb_id = 69187 ON CONFLICT (game_id, language_code) DO NOTHING;
