INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arena Football: Road to Glory', 'Arena Football: Road to Glory is a PlayStation 2 video game developed by Electronic Arts (under their EA Sports brand). It was released on February 21, 2007. The cover features fullback/linebacker Bob McMillen, from ArenaBowl XX''s champion team, the Chicago Rush. The game includes all the rules, rosters, and teams for the AFL season. For the first time the Arena Football minor league, AF2, is included in the series.' FROM games WHERE igdb_id = 17276 ON CONFLICT (game_id, language_code) DO NOTHING;
