INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'XxxHolic: Watanuki no Izayoi Sowa', 'The protagonist of the series is Kimihiro Watanuki, a high school student who is constantly haunted by monsters, ghosts and spirits who are magically attracted to him because of his blood. These monsters are invisible to people without power, so other people brand him as weird or crazy when he is haunted by the spirits. Everything changes when he goes into a store that sells wishes.' FROM games WHERE igdb_id = 194567 ON CONFLICT (game_id, language_code) DO NOTHING;
