INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Betty Boop''s Double Shift', 'Betty dreams of life on the big screen, but she will need to move into the city if she is ever to fulfill her dreams of stardom. You will help Betty make all the money she needs by helping Grampy open "Betty''s" Jazz Club, and work to take the tiny club from rags to riches. With each shift Betty is one step closer to the silver screen as "Betty''s" grows into a spectacular Jazz Club with service so fast and entertainment so great Betty will have no problem raising the cash to fund her big debut!' FROM games WHERE igdb_id = 8455 ON CONFLICT (game_id, language_code) DO NOTHING;
