INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Vegas Casino', 'Vegas Casino consists of five games: Blackjack, Slots, Roulette, Big-6 Money Wheel, and Texas Hold ''Em. The player navigates around a casino map, and selects which game on the floor they would like to play. Gameplay is rendered in 3D, and the player can choose an avatar to represent them. Once the player wins a certain amount of money, they are let into the High Stakes Lounge. Made for the Nintendo DS, the game supports Button, Microphone, and Stylus control methods.' FROM games WHERE igdb_id = 69973 ON CONFLICT (game_id, language_code) DO NOTHING;
