INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Petz: Catz 2', 'Petz: Catz 2, known in Japan as Nyanko to Mahou no Boushi and in Europe as simply Catz, is an adventure game developed by Yuke''s for the Nintendo Wii and PlayStation 2 consoles, published and released by Ubisoft in 2007. It is a spiritual successor to THE DOG Island, in which the player controls a young kitten on a quest to save the world and retrieve the titular Magic Hat back from the evil wolf, Ivlet.' FROM games WHERE igdb_id = 5095 ON CONFLICT (game_id, language_code) DO NOTHING;
