INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Time Ace', 'Time Ace is an aerial combat game developed for the Nintendo DS by Trainwreck Studios and The Farm 51 and published by Konami. The game was released on June 12, 2007. Time Ace is based on the concept that an eccentric inventor from 1914, Dr. Hugo Clock, has formed a plan to travel forward in time to end World War I, but the evil Dr. Klaus Scythe uses the time machine to further his own plan for world domination. The player''s goal is to stop Scythe''s nefarious scheme. The game is similar to Konami''s earlier 1981 arcade game Time Pilot.' FROM games WHERE igdb_id = 21545 ON CONFLICT (game_id, language_code) DO NOTHING;
