INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Little Britain: The Video Game', 'Little Britain: The Video Game is a collection of mini-games presented in the format of an episode from the TV show and players can get interactive with the sketch show characters in a series of eight mini-games featuring Lou and Andy, Vicky Pollard, Mr. Mann, Emily and Florence, Marjorie Dawes, Daffyd Thomas, Judy & Maggie and Letty. Each mini game plays like a sketch from the TV show and to win the game, the player must progress through all the sketches to the end of the show, where the credits will roll.' FROM games WHERE igdb_id = 8557 ON CONFLICT (game_id, language_code) DO NOTHING;
