INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Death Jr. and the Science Fair of Doom', 'Death Jr. and the Science Fair of Doom brings back Death Jr, Pandora and the crew for a new adventure on the Nintendo DS. It''s time for the annual school Science Fair, and DJ has gotten into another mess. He & his pals have unleashed Moloch into the school itself -- now they need to clean up the mess before DJ''s dad finds out. Use the DS touch pad to execute cool scythe combos & switch between Death Jr. and Pandora. Help DJ, Pandora and the crew stop Moloch, save the school and keep out of trouble!' FROM games WHERE igdb_id = 21412 ON CONFLICT (game_id, language_code) DO NOTHING;
