INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'El Tigre: The Adventures of Manny Rivera', 'Havoc has been unleashed on Miracle City! Scores of skeletons roam the streets terrorizing the citizens. Out of the chaos, Manny and his alter ego El Tigre emerge as the city''s last hope. Decide whether to be good or evil. Each action taken in the game will decide the different paths that result in alternate endings to the game.' FROM games WHERE igdb_id = 7995 ON CONFLICT (game_id, language_code) DO NOTHING;
