INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Simpsons: Minutes to Meltdown', 'Enter Springfield for an adventure through the hilarious world of The Simpsons! Guide Homer in a race against time as he tries to prevent a meltdown at the nuclear power plant. Interact with Bart, Mr. Burns, Apu and more of your favorite Springfielders. Avoid hazards like burning tires and giant sinkholes while you steer Homer through his fast-paced, perilous mission. Watch out for Krusty the Clown, Officer Lou and others who try to stop Homer from saving the day.' FROM games WHERE igdb_id = 256656 ON CONFLICT (game_id, language_code) DO NOTHING;
