INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-witcher-crimson-trail', 187249, '2007-11-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4csx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scf8o3.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Witcher: Crimson Trail', 'Geralt, a promising young student, has just completed his training to become an elite monster slayer - a witcher. He has survived arduous tests and intense physical conditioning to become something more than human. Coupled with the esoteric knowledge passed on from veteran witchers, his training has prepared Geralt for whatever evil lurks out in the real world - and has given him the tools to eliminate it. Rumors from local villagers lead him to a dark and twisted forest where a fearsome beast is said to prey on the innocent. Yet as he delves deeper, Geralt soon finds out that a much more insidious evil has taken root in the land, and stopping it will require all of his skill and cunning. Not only will he have to fight his way through legions of monsters across various landscapes, but the decisions he makes along the way will mean the difference between ultimate victory and crushing defeat. Become Geralt, the young witcher, as he sets out on his first adventure - and his final test.' FROM games WHERE igdb_id = 187249 ON CONFLICT (game_id, language_code) DO NOTHING;
