INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saru Getchu Saru Saru Daisakusen', 'A PlayStation Portable exclusive entry into the long running Ape Escape series which was developed by h.a.n.d. and released by Sony Computer Entertainment exclusively in Japan. After kidnapping The Professor, Aki (Akie), Yumi (Sayaka), Kei (Satoru) and Jimmy (Hikaru), Specter goes on to shrink the laboratory with Spike (Kakeru) and Natalie (Natsumi) still inside. On the bright side, the lab is now the perfect size to be disguised as a Pipo Helmet - now, the player will use this gadget to take control over monkeys (Piposaru) in brand new levels to help both protagonists rescue their friends and defeat Specter once again.' FROM games WHERE igdb_id = 79069 ON CONFLICT (game_id, language_code) DO NOTHING;
