INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crash of the Titans', 'Crash of the Titans is the sixth Crash Bandicoot series game. The gameplay has the player explore levels, picking up power-ups to use against enemies as well as for the first time, use fighting combos such as punches and kicks against enemies. When Crash defeats an enemy or destroys an object, a magical substance known as Mojo is released. If the player collects enough Mojo, he will earn either an ability upgrade or a new move.' FROM games WHERE igdb_id = 1190 ON CONFLICT (game_id, language_code) DO NOTHING;
