INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I Spy Fun House', 'Once you enter the FUN HOUSE, there''s no turning back! Only quick wit and nimble fingers can match the illusions and brain-teasing puzzles of the FUN HOUSE, where nothing is as it appears. Solve mystifying riddles, play multi-level games and access bonus rounds to make your escape. Test your brain power with three fast-paced games! Flex your muscles to toss objects from screen-to-screen using the stylus. Eighteen rhyming riddles set across six mind-bending fun house scenes!' FROM games WHERE igdb_id = 47784 ON CONFLICT (game_id, language_code) DO NOTHING;
