INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Real Football 2008', 'Real Soccer 2008 is the fifth entry in Gameloft''s annual series of mobile football games. The gameplay in this edition is mostly identical to the previous iteration. It is played from an isometric birds eye view and has the same controls with the same moves being possible to do. This includes performing lobs, flip-flap tricks and one-two passing.
